head.script:
// [FAIL] gridView 가 편집 상태일때 키를 입력하면
//        onkeydown -> oneditkeydown -> onkeyup -> oneditkeyup 순서로 이벤트가 발생해야 하는데,
//        Body Cell 이 embeddedInput="true" 인 경우 이 순서가 성립하지 않는다.
//        col A = embeddedInput 미사용 (더블클릭으로 편집 진입) -> 가이드대로의 순서
//        col B = embeddedInput="true" (셀 안 입력창에 커서를 두면 편집 상태) -> 순서 불일치

//  seq       : 한 번의 키 조작(누름 -> 뗌) 안에서 이벤트 발생 순번
//  cycleDone : 직전 조작이 끝났는지 여부 (다음 누름 이벤트에서 순번을 1 부터 다시 시작)
scwin.gVar = { "seq" : 0, "cycleDone" : true };



// 이벤트 발생 즉시 한 줄씩 출력 (출력 순서 = 실제 발생 순서)
scwin.logEvent = function (strName, bDown) {
    if (bDown === true && scwin.gVar.cycleDone === true) {
        scwin.gVar.seq = 0;
        scwin.gVar.cycleDone = false;
    }
    scwin.gVar.seq++;
    scwin.setReturnValue("[" + scwin.gVar.seq + "] " + strName);
};



scwin.grid1_onkeydown = function (e) {
    scwin.logEvent("onkeydown", true);
};

scwin.grid1_oneditkeydown = function (info) {
    scwin.logEvent("oneditkeydown (colID=" + info.colID + ")", true);
};

scwin.grid1_onkeyup = function (e) {
    scwin.logEvent("onkeyup", false);
    scwin.gVar.cycleDone = true;
};

scwin.grid1_oneditkeyup = function (info) {
    scwin.logEvent("oneditkeyup (colID=" + info.colID + ")", false);
    scwin.gVar.cycleDone = true;
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
    scwin.gVar.seq = 0;
    scwin.gVar.cycleDone = true;
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
